"use client"

import { useState, useEffect } from "react"

import Stage1TripType from "../../components/tripplanners/Stage1TripType"
import Stage2Location from "../../components/tripplanners/Stage2Location"
import Stage3TripStyle from "../../components/tripplanners/Stage3TripStyle"
import Stage4Suggestions from "../../components/tripplanners/Stage4Suggestions"


// Future group components
// import GroupStage2 from "./components/GroupStage2"
// import GroupStage3 from "./components/GroupStage3"

export default function TripPlan() {

  const [stage, setStage] = useState(1)

  const [formData, setFormData] = useState({
    tripType: "",
    state: "",
    cities: [],
    tripStyles: []
  })

  useEffect(() => {

    const saved = localStorage.getItem("tripPlan")

    if (saved) {
      setFormData(JSON.parse(saved))
    }

  }, [])

  const updateForm = (data) => {

    const updated = { ...formData, ...data }

    setFormData(updated)

    localStorage.setItem(
      "tripPlan",
      JSON.stringify(updated)
    )

  }

  const nextStage = () => {
    setStage(prev => prev + 1)
  }

  return (

    <div className="p-10 flex flex-col gap-8">

      <h2 className="text-xl font-semibold">
        Trip Planner
      </h2>

      {/* STAGE 1 */}
      {stage === 1 && (

        <Stage1TripType
          updateForm={updateForm}
          nextStage={nextStage}
        />

      )}

      {/* SOLO FLOW */}

      {formData.tripType === "solo" && (

        <>

          {stage === 2 && (

            <Stage2Location
              updateForm={updateForm}
              nextStage={nextStage}
            />

          )}

          {stage === 3 && (

            <Stage3TripStyle
              updateForm={updateForm}
              nextStage={nextStage}
            />

          )}

          {stage === 4 && (

            <Stage4Suggestions
              formData={formData}
              updateForm={updateForm}
              nextStage={nextStage}
            />

          )}

        </>

      )}

      {/* GROUP FLOW (future implementation) */}

      {formData.tripType === "group" && (

        <>

          {/*

{stage===2 && (

<GroupStage2
updateForm={updateForm}
nextStage={nextStage}
/>

)}

{stage===3 && (

<GroupStage3
updateForm={updateForm}
nextStage={nextStage}
/>

)}

*/}

        </>

      )}

    </div>

  )

}